package pe.cruzroja.convocatorias.justifications.domain; import java.time.*; import java.util.UUID; public class Justification {public static final int DEADLINE_HOURS=72; private final UUID id,absenceId,volunteerId; private final String reason; private JustificationStatus status=JustificationStatus.PENDIENTE; public Justification(UUID id,UUID absenceId,UUID volunteerId,String reason,LocalDateTime absenceAt,LocalDateTime submittedAt){if(id==null||absenceId==null||volunteerId==null||reason==null||reason.isBlank()||submittedAt.isAfter(absenceAt.plusHours(DEADLINE_HOURS)))throw new IllegalArgumentException("La justificación es inválida o está fuera de plazo");this.id=id;this.absenceId=absenceId;this.volunteerId=volunteerId;this.reason=reason;} public void approve(){ensurePending();status=JustificationStatus.APROBADA;} public void reject(String comment){ensurePending();if(comment==null||comment.isBlank())throw new IllegalArgumentException("Indique el motivo del rechazo");status=JustificationStatus.RECHAZADA;} private void ensurePending(){if(status!=JustificationStatus.PENDIENTE)throw new IllegalStateException("La justificación ya fue resuelta");} public JustificationStatus status(){return status;} }
